# Explicitly inspected implementations. A missing source anchor is a generation error.
def loc(file,token,why):
 text=(ROOT/file).read_text(encoding='utf-8').splitlines()
 hits=[i for i,l in enumerate(text,1) if token in l]
 if not hits: raise ValueError((file,token))
 # Prefer definitions over event bindings/calls.
 defs=[i for i in hits if re.search(r'(const\s+'+re.escape(token.split('(')[0])+r'\s*=|function\s+'+re.escape(token.split('(')[0])+r'\b|(?:public|private|protected) .*\b'+re.escape(token.split('(')[0])+r'\s*\()',text[i-1])]
 i=(defs or hits)[0]
 return dict(file=file,path=str(ROOT/file),line=i,symbol=token,why=why,excerpt=text[i-1].strip())
