 for d in D:
  d['anchors'] += [loc(*x) for x in extras.get(d['n'],[])]
  d['apis'] += api_extra.get(d['n'],[])
 for d in D:
  # Add persistence locations so the chain really reaches the database.
  storage_tokens=re.findall(r'\b(?:t_|s3_)[a-z_]+',d['storage'])
  for token in dict.fromkeys(storage_tokens):
   candidates=[]
   for p in (ROOT/'backend/src/main').rglob('*.java'):
    if token in p.read_text(encoding='utf-8') and '@Table' in p.read_text(encoding='utf-8'):candidates.append(p)
   exact=[p for p in candidates if re.search(r'@Table\s*\(\s*name\s*=\s*"'+token+'"',p.read_text(encoding='utf-8'))]
   if exact:d['anchors'].append(loc(str(exact[0].relative_to(ROOT)).replace('\\','/'),token,'持久化实体对应的实际表名'))
 (E/'catalog.json').write_text(json.dumps(sorted(D,key=lambda x:x['n']),ensure_ascii=False,indent=2),encoding='utf-8')
